pragma solidity ^0.8.20;

// OpenZeppelin Imports
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

// Chainlink Contracts
// Source: @chainlink/contracts/src/v0.8/interfaces/VRFCoordinatorV2Interface.sol
interface VRFCoordinatorV2Interface {
  function getRequestConfig()
    external
    view
    returns (
      uint16,
      uint32,
      bytes32[] memory
    );

  function requestRandomWords(
    bytes32 keyHash,
    uint64 subId,
    uint16 minimumRequestConfirmations,
    uint32 callbackGasLimit,
    uint32 numWords
  ) external returns (uint256 requestId);

  function createSubscription() external returns (uint64 subId);

  function getSubscription(uint64 subId)
    external
    view
    returns (
      uint96 balance,
      uint64 reqCount,
      address owner,
      address[] memory consumers
    );

  function requestSubscriptionOwnerTransfer(uint64 subId, address newOwner) external;

  function addConsumer(uint64 subId, address consumer) external;

  function removeConsumer(uint64 subId, address consumer) external;

  function cancelSubscription(uint64 subId, address to) external;

  function getCommitment(uint256 requestId) external view returns (bytes32);
}

// Source: @chainlink/contracts/src/v0.8/vrf/VRFConsumerBaseV2.sol
abstract contract VRFConsumerBaseV2 {
  address public s_vrfCoordinator;

  function fulfillRandomWords(uint256 requestId, uint256[] memory randomWords) internal virtual;

  constructor(address vrfCoordinator) {
    s_vrfCoordinator = vrfCoordinator;
  }
}

/**
 * @title GameToken
 * @dev The ERC20 token for the MMORPG's play-to-earn economy.
 * @dev This contract would be deployed separately, and its ownership transferred to the main MMORPG contract.
 */
contract GameToken is ERC20, Ownable {
    constructor() ERC20("MMORPG Gold", "MMG") {}

    /**
     * @dev Mints tokens. Can only be called by the owner (the MMORPG contract).
     */
    function mint(address to, uint256 amount) public onlyOwner {
        _mint(to, amount);
    }
}

/**
 * @title GameItem
 * @dev The ERC721 NFT for unique in-game items with dynamic stats.
 * @dev This contract would be deployed separately, and its ownership transferred to the main MMORPG contract.
 */
contract GameItem is ERC721, ERC721Enumerable, Ownable {
    uint256 private _nextTokenId;

    struct ItemStats {
        uint32 level;
        uint32 power;
        uint32 durability;
        uint64 usageCount;
    }

    mapping(uint256 => ItemStats) public itemStats;

    constructor() ERC721("MMORPG Item", "MMI") {}

    /**
     * @dev Mints a new item. Can only be called by the owner (the MMORPG contract).
     */
    function mint(address to) public onlyOwner returns (uint256) {
        uint256 tokenId = _nextTokenId++;
        _safeMint(to, tokenId);
        return tokenId;
    }

    /**
     * @dev Sets the stats for a given item. Can only be called by the owner.
     */
    function setStats(uint256 tokenId, ItemStats calldata stats) public onlyOwner {
        require(_exists(tokenId), "GameItem: URI query for nonexistent token");
        itemStats[tokenId] = stats;
    }

    function _beforeTokenTransfer(address from, address to, uint256 firstTokenId, uint256 batchSize) internal virtual override(ERC721, ERC721Enumerable) {
        super._beforeTokenTransfer(from, to, firstTokenId, batchSize);
    }

    function supportsInterface(bytes4 interfaceId) public view virtual override(ERC721, ERC721Enumerable) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

/**
 * @title LandNFT
 * @dev The ERC721 NFT for in-game land ownership and rentals.
 * @dev This contract would be deployed separately, and its ownership transferred to the main MMORPG contract.
 */
contract LandNFT is ERC721, ERC721Enumerable, Ownable {
    uint256 private _nextTokenId;

    struct LandInfo {
        address renter;
        uint64 rentDueDate;
        uint256 rentalPrice; // Per day
    }

    mapping(uint256 => LandInfo) public landInfo;

    constructor() ERC721("MMORPG Land", "MML") {}

    function mint(address to) public onlyOwner returns (uint256) {
        uint256 tokenId = _nextTokenId++;
        _safeMint(to, tokenId);
        return tokenId;
    }

    function setRentalInfo(uint256 tokenId, address renter, uint64 rentDueDate, uint256 rentalPrice) public onlyOwner {
        require(_exists(tokenId), "LandNFT: Token does not exist");
        landInfo[tokenId] = LandInfo(renter, rentDueDate, rentalPrice);
    }

    function _beforeTokenTransfer(address from, address to, uint256 firstTokenId, uint256 batchSize) internal virtual override(ERC721, ERC721Enumerable) {
        super._beforeTokenTransfer(from, to, firstTokenId, batchSize);
    }

    function supportsInterface(bytes4 interfaceId) public view virtual override(ERC721, ERC721Enumerable) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

/**
 * @title MMORPG
 * @dev The primary deployable contract for the MMORPG, managing all core game logic.
 * This monolithic contract is designed to fulfill specific project constraints. In a production
 * environment, this logic would be decentralized across multiple, upgradeable contracts.
 */
contract MMORPG is Ownable, ReentrancyGuard, VRFConsumerBaseV2 {
    using EnumerableSet for EnumerableSet.AddressSet;

    // --- Game Asset Contracts ---
    GameToken public gameToken;
    GameItem public gameItem;
    LandNFT public landNFT;

    // --- Player Data ---
    struct PlayerProfile {
        string name;
        uint256 reputation; // Affects drop rates
        uint256 guildId;
        bool registered;
    }
    mapping(address => PlayerProfile) public players;
    uint256 public constant MAX_REPUTATION = 1000;

    // --- Guild Management ---
    enum GuildRank { NONE, MEMBER, OFFICER, LEADER }
    struct GuildMember {
        address addr;
        GuildRank rank;
    }
    struct Guild {
        string name;
        mapping(address => GuildMember) members;
        EnumerableSet.AddressSet memberSet;
    }
    mapping(uint256 => Guild) internal guilds;
    uint256 private _nextGuildId;

    // --- P2E Tokenomics & Linear Vesting ---
    struct VestingSchedule {
        uint256 totalAmount;
        uint64 start;
        uint64 duration;
        uint256 released;
    }
    mapping(address => VestingSchedule) public vestingSchedules;

    // --- Crafting System (Chainlink VRF) ---
    uint64 private s_subscriptionId;
    bytes32 private s_keyHash; // Gas lane
    uint32 private s_callbackGasLimit = 100000;
    uint16 private s_requestConfirmations = 3;
    uint32 private s_numWords = 1;
    mapping(uint256 => address) private s_vrfRequestToCrafter;

    // --- Marketplace (Auctions) ---
    enum AuctionType { None, English, Dutch }
    struct Auction {
        AuctionType aType;
        address payable seller;
        uint256 nftId;
        address nftContract;
        uint256 startPrice;
        uint256 endPrice; // For Dutch auction
        uint64 duration;
        uint64 startTime;
        address highestBidder;
        uint256 highestBid;
    }
    mapping(uint256 => Auction) public auctions; // auctionId => Auction
    uint256 private _nextAuctionId = 1;

    // --- PvP Tournaments ---
    struct Tournament {
        uint256 prizePool;
        address winner;
        bool ended;
        EnumerableSet.AddressSet participants;
    }
    mapping(uint256 => Tournament) internal tournaments;
    uint256 private _nextTournamentId = 1;

    // --- Seasonal Events ---
    struct Season {
        uint64 startTime;
        uint64 endTime;
        bool active;
        mapping(address => bool) claimedReward;
    }
    Season public currentSeason;

    // --- Events ---
    event PlayerRegistered(address indexed player, string name);
    event GuildCreated(uint256 indexed guildId, string name, address indexed leader);
    event CraftingRequested(uint256 indexed requestId, address indexed crafter);
    event CraftingFulfilled(uint256 indexed requestId, uint256 newItemId, bool success);
    event AuctionCreated(uint256 indexed auctionId, address indexed seller, address indexed nftContract, uint256 nftId);
    event BidPlaced(uint256 indexed auctionId, address indexed bidder, uint256 amount);


    /**
     * @dev The constructor is empty of parameters as required.
     * It calls the VRFConsumerBaseV2 constructor with a hard-coded Chainlink VRF Coordinator
     * address for the Sepolia testnet. For other networks, this address must be changed.
     */
    constructor() VRFConsumerBaseV2(0x8103B0a8a00BE2ddc778e28064fa362446650ADC) {}

    /**
     * @dev Initializes the main contract with dependent contract addresses and VRF settings.
     * Can only be called once by the owner. The owner must first deploy the GameToken,
     * GameItem, and LandNFT contracts, then pass their addresses here. The owner should also
     * transfer ownership of those contracts to this MMORPG contract.
     */
    function initialize(
        address _gameToken,
        address _gameItem,
        address _landNFT,
        uint64 _subscriptionId,
        bytes32 _keyHash
    ) public onlyOwner {
        require(address(gameToken) == address(0), "Already initialized");
        gameToken = GameToken(_gameToken);
        gameItem = GameItem(_gameItem);
        landNFT = LandNFT(_landNFT);
        s_subscriptionId = _subscriptionId;
        s_keyHash = _keyHash;
    }

    // --- Player & Reputation ---
    function registerPlayer(string calldata name) external {
        require(!players[msg.sender].registered, "Player already registered");
        players[msg.sender] = PlayerProfile(name, 100, 0, true);
        emit PlayerRegistered(msg.sender, name);
    }

    function _adjustReputation(address player, bool increase) internal {
        if (increase && players[player].reputation < MAX_REPUTATION) {
            players[player].reputation++;
        } else if (!increase && players[player].reputation > 0) {
            players[player].reputation--;
        }
    }

    // --- Crafting ---
    function requestCraft() external returns (uint256 requestId) {
        require(players[msg.sender].registered, "Player not registered");
        // In a real system, this would transfer/burn crafting materials.
        gameToken.transferFrom(msg.sender, address(this), 10 * 10**18);

        requestId = VRFCoordinatorV2Interface(s_vrfCoordinator).requestRandomWords(
            s_keyHash,
            s_subscriptionId,
            s_requestConfirmations,
            s_callbackGasLimit,
            s_numWords
        );
        s_vrfRequestToCrafter[requestId] = msg.sender;
        emit CraftingRequested(requestId, msg.sender);
        return requestId;
    }

    function fulfillRandomWords(uint256 _requestId, uint256[] memory _randomWords) internal override {
        address crafter = s_vrfRequestToCrafter[_requestId];
        require(crafter != address(0), "Invalid VRF request");
        delete s_vrfRequestToCrafter[_requestId];

        uint256 randomness = _randomWords[0];
        uint256 baseSuccessChance = 50; // 50%
        uint256 reputationBonus = players[crafter].reputation / 100; // 0-10% bonus
        uint256 successRoll = (randomness % 100);

        if (successRoll < baseSuccessChance + reputationBonus) {
            uint256 newItemId = gameItem.mint(crafter);
            uint32 power = uint32((randomness >> 32) % 100) + 1;
            gameItem.setStats(newItemId, GameItem.ItemStats(1, power, 100, 0));
            _adjustReputation(crafter, true);
            emit CraftingFulfilled(_requestId, newItemId, true);
        } else {
             _adjustReputation(crafter, false);
            emit CraftingFulfilled(_requestId, 0, false);
        }
    }

    // --- Marketplace ---
    function createEnglishAuction(address _nftContract, uint256 _nftId, uint256 _startPrice, uint64 _duration) external nonReentrant {
        require(_nftContract == address(gameItem) || _nftContract == address(landNFT), "Invalid NFT contract");
        ERC721(_nftContract).transferFrom(msg.sender, address(this), _nftId);

        uint256 auctionId = _nextAuctionId++;
        auctions[auctionId] = Auction({
            aType: AuctionType.English,
            seller: payable(msg.sender),
            nftId: _nftId,
            nftContract: _nftContract,
            startPrice: _startPrice,
            endPrice: 0,
            duration: _duration,
            startTime: uint64(block.timestamp),
            highestBidder: address(0),
            highestBid: _startPrice
        });
        emit AuctionCreated(auctionId, msg.sender, _nftContract, _nftId);
    }

    function bid(uint256 auctionId) external payable nonReentrant {
        Auction storage auction = auctions[auctionId];
        require(auction.aType == AuctionType.English, "Not an English auction");
        require(block.timestamp < auction.startTime + auction.duration, "Auction ended");
        require(msg.value > auction.highestBid, "Bid too low");

        if (auction.highestBidder != address(0)) {
            payable(auction.highestBidder).transfer(auction.highestBid);
        }
        auction.highestBidder = msg.sender;
        auction.highestBid = msg.value;
        emit BidPlaced(auctionId, msg.sender, msg.value);
    }

    function endAuction(uint256 auctionId) external nonReentrant {
        Auction storage auction = auctions[auctionId];
        require(auction.aType != AuctionType.None, "Auction does not exist");
        require(block.timestamp >= auction.startTime + auction.duration, "Auction not yet ended");

        if (auction.highestBidder != address(0)) {
            ERC721(auction.nftContract).transferFrom(address(this), auction.highestBidder, auction.nftId);
            auction.seller.transfer(auction.highestBid);
        } else {
            ERC721(auction.nftContract).transferFrom(address(this), auction.seller, auction.nftId);
        }
        delete auctions[auctionId];
    }

    // --- P2E Vesting ---
    function _grantVestedTokens(address to, uint256 totalAmount, uint64 duration) internal {
        vestingSchedules[to] = VestingSchedule({
            totalAmount: totalAmount,
            start: uint64(block.timestamp),
            duration: duration,
            released: 0
        });
    }

    function claimableAmount(address account) public view returns (uint256) {
        VestingSchedule storage schedule = vestingSchedules[account];
        if (schedule.totalAmount == 0) return 0;
        uint256 elapsedTime = block.timestamp > schedule.start ? block.timestamp - schedule.start : 0;
        if (elapsedTime >= schedule.duration) {
            return schedule.totalAmount - schedule.released;
        } else {
            uint256 vestedAmount = (schedule.totalAmount * elapsedTime) / schedule.duration;
            return vestedAmount - schedule.released;
        }
    }

    function claimVestedTokens() external nonReentrant {
        uint256 amount = claimableAmount(msg.sender);
        require(amount > 0, "No tokens to claim");
        vestingSchedules[msg.sender].released += amount;
        gameToken.mint(msg.sender, amount);
    }

    // --- Anti-Bot (ZKP Placeholder) ---
    /**
     * @dev A placeholder for a ZKP-gated action. In a real system, this would call a
     * separate, highly-optimized ZK verifier contract (e.g., a Groth16 verifier).
     */
    function performActionWithProof(bytes calldata proof, bytes calldata publicInputs) external {
        require(_verifyBotProof(proof, publicInputs), "Invalid ZK proof");
        // Gated action, e.g., claim a rare, bot-protected reward
        _grantVestedTokens(msg.sender, 1000 * 10**18, 30 days);
    }

    function _verifyBotProof(bytes calldata, bytes calldata) internal pure returns (bool) {
        // A real implementation would be: `return Verifier.verify(proof, publicInputs);`
        return true; // Assume valid for this implementation
    }

    // --- Cross-Server Transfers (Bridge Placeholder) ---
    /**
     * @dev Locks an asset for transfer to another "server" (chain). This is a simplified
     * representation of a bridge lock mechanism. A real bridge requires off-chain relayers.
     */
    function lockAssetForTransfer(address _nftContract, uint256 _tokenId, uint256 _targetChainId) external {
        require(_nftContract == address(gameItem) || _nftContract == address(landNFT), "Invalid NFT contract");
        ERC721(_nftContract).transferFrom(msg.sender, address(this), _tokenId);
        // An event would be emitted here for off-chain bridge components to observe.
    }

    // --- PvP Tournaments & Seasonal Events ---
    function endTournament(uint256 _tournamentId, address _winner) external onlyOwner {
        Tournament storage t = tournaments[_tournamentId];
        require(!t.ended, "Tournament already ended");
        t.winner = _winner;
        t.ended = true;
        _grantVestedTokens(_winner, t.prizePool, 90 days); // Grant prize with 90-day vesting
    }

    function startSeason(uint64 _duration) external onlyOwner {
        require(!currentSeason.active, "A season is already active");
        currentSeason.startTime = uint64(block.timestamp);
        currentSeason.endTime = uint64(block.timestamp) + _duration;
        currentSeason.active = true;
    }

    function claimSeasonalReward() external {
        require(currentSeason.active, "No active season");
        require(block.timestamp > currentSeason.endTime, "Season has not ended");
        require(!currentSeason.claimedReward[msg.sender], "Reward already claimed");

        currentSeason.claimedReward[msg.sender] = true;
        uint256 newItemId = gameItem.mint(msg.sender);
        gameItem.setStats(newItemId, GameItem.ItemStats(10, 100, 500, 0));
    }
}

